insert into settings (id, store_name, tagline, tagline_en, whatsapp_number, bank_name, bank_account, bank_holder, qris_image_url, cutoff_time, min_order_retail, min_order_business, free_delivery_retail, free_delivery_business, catch_weight_buffer_pct, max_days_ahead, instagram, address_line, announcement, announcement_en, hero_image_url, about_image_url) values (1, 'Dipasaria', 'Protein pilihan untuk dapur Jakarta', 'Trusted protein for Jakarta''s kitchens', '6281100000000', 'BCA', '0000000000', 'PT Dipasaria', null, '20:00', 150000, 750000, 250000, 750000, 5, 6, 'dipasaria.id', 'Jakarta Utara', null, null, null, null)
insert into categories (id, slug, name, name_en, description, description_en, sort, icon, image_url, is_seafood) values
  ('c_ikan', 'ikan-segar', 'Ikan segar', 'Fresh Fish', 'Dipilih dari lelang Muara Baru sebelum subuh, dengan jenis dan ukuran yang jelas.', 'Auctioned at Muara Baru before dawn, named by species, graded by size.', 1, 'fish', '/images/site/cat-ikan-segar.jpg', true),
  ('c_udang', 'udang-cumi', 'Udang dan cumi', 'Shrimp & Squid', 'Udang vaname dan windu dengan ukuran yang jelas, cumi, sotong, kepiting bakau, dan kerang hijau, siap dibersihkan sesuai pesanan.', 'Sized vannamei and tiger prawns, squid, cuttlefish, mud crab and green mussels, cleaned to order.', 2, 'shrimp', '/images/site/cat-udang-cumi.jpg', true),
  ('c_beku', 'seafood-beku', 'Seafood beku', 'Frozen Seafood', 'Fillet dan potongan beku untuk persediaan di freezer, tanpa risiko basi.', 'Fillets and portions for the freezer, no spoilage risk.', 3, 'snow', '/images/site/cat-seafood-beku.jpg', true),
  ('c_ayam', 'ayam', 'Ayam halal', 'Halal Chicken', 'Ayam dari rumah potong bersertifikat halal, tersedia beku, serta segar khusus untuk akun bisnis.', 'Cut chicken from halal-certified slaughterhouses, frozen or fresh for business accounts.', 4, 'chicken', '/images/site/cat-ayam.jpg', false),
  ('c_olahan', 'frozen-food', 'Olahan beku', 'Frozen Food', 'Nugget, sosis, dan bakso ikan dari merek yang terdaftar di BPOM dan berlogo halal.', 'Nuggets, sausages and fish balls from BPOM-registered, halal-labelled brands.', 5, 'box', '/images/site/cat-frozen-food.jpg', false),
  ('c_telur', 'telur', 'Telur', 'Eggs', 'Telur ayam negeri, ayam kampung, bebek, dan puyuh; per rak, atau per peti untuk kebutuhan restoran.', 'Chicken, free-range, duck and quail eggs; by the tray, or by the crate for restaurants.', 6, 'egg', '/images/site/cat-telur.jpg', false),
  ('c_paket', 'paket-hemat', 'Paket hemat', 'Value Boxes', 'Paket isi freezer yang lebih hemat daripada membeli satuan.', 'Freezer-ready boxes priced below buying the items separately.', 8, 'box', '/images/products/kotak-freezer-keluarga.jpg', false),
  ('c_bumbu', 'bumbu-dapur', 'Bumbu dapur', 'Pantry & Condiments', 'Kebutuhan dapur yang rutin Anda beli setiap minggu, dikirim dalam pengiriman yang sama.', 'The kitchen staples you buy every week, in the same delivery.', 7, 'bottle', '/images/site/cat-bumbu-dapur.jpg', false)
insert into products (id, slug, category_id, name, name_en, scientific_name, aliases, description, description_en, origin, origin_en, storage_class, storage_note, storage_note_en, is_catch_weight, available_today, is_active, is_featured, image_url, icon, sort) values
  ('p_kakap', 'kakap-merah', 'c_ikan', 'Kakap Merah', 'Malabar Snapper', 'Lutjanus malabaricus', array['bambangan','red snapper','kakap']::text[], 'Kakap merah asli, bukan Red Bass yang kerap dijual dengan nama yang sama. Dagingnya putih dan padat, cocok dikukus, dibakar, atau digoreng.', 'The true red snapper, not the Red Bass often sold under that name. Firm white flesh for steaming, grilling or frying.', 'Muara Baru, didaratkan menjelang subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, true, '/images/products/kakap-merah.jpg', 'fish', 1),
  ('p_kerapu', 'kerapu', 'c_ikan', 'Kerapu', 'Orange-spotted Grouper', 'Epinephelus coioides', array['grouper','kerapu lumpur','kerapu macan']::text[], 'Kerapu budidaya dengan pasokan yang stabil. Pilihan utama restoran untuk hidangan ikan kukus.', 'Farmed grouper with a steady supply. The restaurant choice for steamed whole fish.', 'Tambak Lampung dan Kepulauan Seribu, melalui Muara Baru', 'Lampung and Seribu Islands farms via Muara Baru', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, true, '/images/products/kerapu.jpg', 'fish', 2),
  ('p_kembung', 'kembung', 'c_ikan', 'Kembung', 'Indian Mackerel', 'Rastrelliger kanagurta', array['mackerel','kembung banjar']::text[], 'Ikan harian yang kaya omega-3. Andalan dapur rumah makan Padang dan warung.', 'The everyday fish, high in omega-3. Daily volume for Padang kitchens and warungs.', 'Muara Baru, didaratkan menjelang subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, '/images/products/kembung.jpg', 'fish', 3),
  ('p_tongkol', 'tongkol', 'c_ikan', 'Tongkol', 'Mackerel Tuna', 'Euthynnus affinis', array['tuna','tongkol abu']::text[], 'Tongkol segar untuk balado, pindang, dan tongkol suwir.', 'Fresh mackerel tuna for balado, pindang and shredded dishes.', 'Muara Baru, didaratkan menjelang subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, '/images/products/tongkol.jpg', 'fish', 4),
  ('p_bandeng', 'bandeng', 'c_ikan', 'Bandeng', 'Milkfish', 'Chanos chanos', array['milkfish','bandeng presto']::text[], 'Bandeng dari tambak Lampung, dengan pilihan cabut duri untuk santapan keluarga.', 'Lampung pond milkfish, with a deboning option for families.', 'Tambak Lampung, melalui Muara Baru', 'Lampung ponds via Muara Baru', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, '/images/products/bandeng.jpg', 'fish', 5),
  ('p_baronang', 'baronang', 'c_ikan', 'Baronang', 'Rabbitfish', 'Siganus spp.', array['rabbitfish','beronang']::text[], 'Ikan bakar favorit restoran seafood. Dagingnya manis dan tidak amis.', 'The seafood restaurant grilling favourite: sweet flesh, never fishy.', 'Muara Baru, didaratkan menjelang subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, false, true, false, '/images/products/baronang.jpg', 'fish', 6),
  ('p_bawal', 'bawal-putih', 'c_ikan', 'Bawal Putih', 'Silver Pomfret', 'Pampus argenteus', array['pomfret','bawal']::text[], 'Bawal putih pilihan untuk hidangan kukus khas Tionghoa-Indonesia.', 'Premium silver pomfret for Chinese-Indonesian steamed dishes.', 'Muara Baru, didaratkan menjelang subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, '/images/products/bawal-putih.jpg', 'fish', 7),
  ('p_nila', 'nila-merah', 'c_ikan', 'Nila Merah', 'Red Tilapia', 'Oreochromis sp.', array['tilapia','nila']::text[], 'Nila budidaya Jawa Barat dengan ukuran seragam. Setelah difillet, aman dan mudah disantap anak-anak.', 'West Java farmed tilapia, consistent sizing, child-friendly when filleted.', 'Kolam budidaya Sukabumi dan Indramayu', 'Sukabumi and Indramayu ponds', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, '/images/products/nila-merah.jpg', 'fish', 8),
  ('p_kakap_putih', 'kakap-putih', 'c_ikan', 'Kakap Putih', 'Barramundi', 'Lates calcarifer', array['barramundi','seabass','sea bass','kakap']::text[], 'Kakap putih budidaya dengan daging putih tebal dan rasa lembut. Cocok untuk fillet goreng, steak panggang, atau sup ikan.', 'Farmed barramundi with thick white flesh and a mild flavour, for pan-fried fillets, grilled steaks or fish soup.', 'Tambak Lampung dan Situbondo, melalui agen tetap', 'Lampung and Situbondo farms via regular agents', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, true, null, 'fish', 9),
  ('p_tenggiri_utuh', 'tenggiri-utuh', 'c_ikan', 'Tenggiri Utuh', 'Spanish Mackerel', 'Scomberomorus commerson', array['tenggiri','king mackerel','spanish mackerel']::text[], 'Tenggiri utuh dengan daging padat dan gurih, untuk steak goreng, pempek, atau otak-otak buatan sendiri.', 'Whole Spanish mackerel with firm, savoury flesh for fried steaks, pempek or home-made otak-otak.', 'Laut Jawa dan Natuna, didaratkan di Muara Baru', 'Java Sea and Natuna, landed at Muara Baru', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, null, 'fish', 10),
  ('p_kuwe', 'ikan-kuwe', 'c_ikan', 'Kuwe', 'Giant Trevally', 'Caranx ignobilis', array['kuwe','trevally','GT','ikan kue']::text[], 'Kuwe berdaging tebal dan padat, favorit untuk ikan bakar dan sup asam pedas.', 'Thick, firm trevally, a favourite for grilling and hot-and-sour soup.', 'Muara Baru, didaratkan menjelang subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, null, 'fish', 11),
  ('p_selar', 'selar', 'c_ikan', 'Selar Kuning', 'Yellowstripe Scad', 'Selaroides leptolepis', array['selar','scad','ikan selar']::text[], 'Selar kuning ukuran kecil, gurih digoreng kering atau dimasak balado. Pilihan hemat untuk lauk harian.', 'Small yellowstripe scad, crisp when fried or cooked balado. An economical everyday choice.', 'Muara Baru, didaratkan menjelang subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, null, 'fish', 12),
  ('p_udang', 'udang-vaname', 'c_udang', 'Udang Vaname Segar', 'Whiteleg Shrimp', 'Litopenaeus vannamei', array['shrimp','prawn','udang putih','vannamei']::text[], 'Udang vaname dari tambak. Angka ukuran menunjukkan jumlah ekor per kilogram. Tanpa perendaman penambah berat.', 'Pond-raised vannamei, sold per kg (size = pieces per kg). No weight-adding soak.', 'Tambak Lampung dan Indramayu', 'Lampung and Indramayu ponds', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, true, '/images/products/udang-vaname.jpg', 'shrimp', 13),
  ('p_cumi', 'cumi-segar', 'c_udang', 'Cumi Segar', 'Squid', 'Loligo spp.', array['squid','sotong','cumi-cumi']::text[], 'Cumi segar dari lelang subuh, dapat dibersihkan dan dipotong cincin sesuai pesanan.', 'Fresh squid from the dawn auction; can be cleaned and cut into rings.', 'Muara Baru, didaratkan menjelang subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, true, null, 'squid', 14),
  ('p_windu', 'udang-windu', 'c_udang', 'Udang Windu', 'Black Tiger Prawn', 'Penaeus monodon', array['windu','tiger prawn','udang besar']::text[], 'Udang windu tambak dengan daging tebal dan manis. Ukuran besar untuk udang bakar, udang saus Padang, atau hidangan istimewa.', 'Pond-raised tiger prawns with thick, sweet flesh, large enough for grilling and saus Padang.', 'Tambak tradisional Sidoarjo dan Lampung', 'Traditional ponds, Sidoarjo and Lampung', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, true, null, 'shrimp', 15),
  ('p_kepiting', 'kepiting-bakau', 'c_udang', 'Kepiting Bakau', 'Mud Crab', 'Scylla serrata', array['kepiting','mud crab','crab']::text[], 'Kepiting bakau dikirim hidup, dengan capit diikat. Daging manis untuk kepiting saus Padang, lada hitam, atau asam manis.', 'Live mud crab with tied claws; sweet meat for saus Padang, black pepper or sweet-and-sour crab.', 'Pengepul tetap di Muara Angke dan Kalimantan Utara', 'Regular traders, Muara Angke and North Kalimantan', 'chilled', 'Dikirim hidup. Simpan di tempat sejuk dan lembap, lalu masak pada hari yang sama.', 'Delivered live. Keep cool and damp, and cook the same day.', true, true, true, false, null, 'shrimp', 16),
  ('p_kerang', 'kerang-hijau', 'c_udang', 'Kerang Hijau', 'Green Mussels', 'Perna viridis', array['kerang','mussel','kijing']::text[], 'Kerang hijau segar yang sudah dibersihkan dari teritip, siap dikukus atau dimasak saus Padang.', 'Fresh green mussels cleaned of barnacles, ready to steam or cook in saus Padang.', 'Budidaya Cilincing, dipanen pagi hari', 'Cilincing farms, harvested in the morning', 'chilled', 'Simpan pada suhu 0–4 °C dan masak pada hari yang sama.', 'Keep at 0–4 °C and cook the same day.', false, true, true, false, null, 'shrimp', 17),
  ('p_sotong', 'sotong', 'c_udang', 'Sotong', 'Cuttlefish', 'Sepia pharaonis', array['sotong','cuttlefish','cumi sotong']::text[], 'Sotong berdaging tebal dan kenyal, cocok untuk sotong bakar, goreng tepung, atau dimasak hitam dengan tintanya.', 'Thick, tender cuttlefish for grilling, battering, or cooking black in its own ink.', 'Muara Baru, didaratkan menjelang subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, null, 'squid', 18),
  ('p_udang_beku', 'udang-kupas-beku', 'c_beku', 'Udang Vaname Kupas Belah Punggung Beku', 'Peeled & Deveined Shrimp', 'Litopenaeus vannamei', array['udang beku','frozen shrimp','pd shrimp']::text[], 'Udang kupas belah punggung, dibekukan per ekor (IQF), siap ditumis. Andalan persediaan freezer di rumah.', 'Peeled, deveined, IQF shrimp ready to stir-fry. The household freezer staple.', 'Gudang pendingin di Lampung', 'Lampung cold storage', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/udang-kupas-beku.jpg', 'shrimp', 19),
  ('p_dori', 'dori-fillet', 'c_beku', 'Fillet Dori Beku', 'Pangasius Fillet', 'Pangasius hypophthalmus', array['dory','patin fillet','ikan dori']::text[], 'Fillet dori tanpa duri untuk fish and chips, menu kafe, dan menu anak.', 'Boneless pangasius fillet for fish and chips, cafés and children''s menus.', 'Unit pengolahan di Lampung (bersertifikat SKP dan HACCP)', 'Lampung processor (SKP/HACCP)', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/dori-fillet.jpg', 'fillet', 20),
  ('p_tuna', 'tuna-saku', 'c_beku', 'Tuna Saku Beku', 'Yellowfin Tuna Saku', 'Thunnus albacares', array['tuna','saku','tuna loin']::text[], 'Tuna saku berkualitas sashimi, layak disajikan mentah setelah dicairkan dengan benar.', 'Tuna saku, sashimi-ready when thawed correctly.', 'Bitung, melalui distributor di Jakarta', 'Bitung, via Jakarta distributor', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/tuna-saku.jpg', 'fillet', 21),
  ('p_salmon', 'salmon-fillet', 'c_beku', 'Fillet Salmon Beku', 'Atlantic Salmon Portion', 'Salmo salar', array['salmon','salmon norway']::text[], 'Potongan salmon Norwegia dari importir berizin, 200 g per potong, siap dipanggang.', 'Imported salmon portions from a licensed importer, cut to 200 g ready to grill.', 'Norwegia, melalui importir berizin di Jakarta', 'Norway, licensed Jakarta importer', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/salmon-fillet.jpg', 'fillet', 22),
  ('p_tenggiri', 'tenggiri-steak', 'c_beku', 'Tenggiri Steak Beku', 'Spanish Mackerel Steak', 'Scomberomorus commerson', array['tenggiri','mackerel steak']::text[], 'Steak tenggiri untuk dibakar atau digoreng, juga cocok sebagai bahan pempek dan otak-otak.', 'Spanish mackerel steaks for grilling and frying, or for pempek and otak-otak.', 'Muara Baru, dibekukan dalam 4 jam setelah dipilih', 'Muara Baru, frozen within 4 hours', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/tenggiri-steak.jpg', 'fillet', 23),
  ('p_cumi_ring', 'cumi-ring-beku', 'c_beku', 'Cumi Ring Beku', 'Frozen Squid Rings', 'Loligo spp.', array['calamari','cumi ring','cumi goreng tepung']::text[], 'Cumi yang sudah dibersihkan dan dipotong cincin, dibekukan cepat per potong. Siap digoreng tepung atau ditumis.', 'Cleaned squid cut into rings and individually quick-frozen, ready to batter or stir-fry.', 'Pengolah bersertifikat SKP/HACCP di Jawa Timur', 'SKP/HACCP-certified processor, East Java', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, null, 'squid', 24),
  ('p_fillet_kakap', 'fillet-kakap-beku', 'c_beku', 'Fillet Kakap Merah Beku', 'Frozen Red Snapper Fillet', 'Lutjanus malabaricus', array['fillet kakap','snapper fillet','kakap fillet']::text[], 'Fillet kakap merah berkulit tanpa duri, dibekukan per potong (IQF). Porsi seragam untuk menu restoran dan makan malam keluarga.', 'Skin-on, boneless red snapper fillets, individually quick-frozen. Uniform portions for restaurant menus and family dinners.', 'Diolah dari lelang Muara Baru, dibekukan dalam 4 jam', 'Cut from the Muara Baru auction, frozen within 4 hours', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, null, 'fillet', 25),
  ('p_sayap', 'sayap-ayam-beku', 'c_ayam', 'Sayap Ayam Beku', 'Chicken Wings', null, array['wings','chicken wing']::text[], 'Sayap ayam dari rumah potong bersertifikat halal dan ber-NKV, dibekukan dalam kondisi segar.', 'Chicken wings from a halal-certified, NKV-registered slaughterhouse, frozen fresh.', 'Rumah potong bersertifikat halal di Jawa Barat', 'Halal-certified slaughterhouse, West Java', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/sayap-ayam-beku.jpg', 'chicken', 26),
  ('p_paha', 'paha-ayam-beku', 'c_ayam', 'Paha Ayam Beku', 'Chicken Thigh', null, array['thigh','paha bawah','paha atas']::text[], 'Paha ayam utuh dengan ukuran seragam, 180–220 g per potong.', 'Whole chicken thighs, uniform 180–220 g pieces.', 'Rumah potong bersertifikat halal di Jawa Barat', 'Halal-certified slaughterhouse, West Java', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/paha-ayam-beku.jpg', 'chicken', 27),
  ('p_dada', 'dada-fillet-ayam', 'c_ayam', 'Fillet Dada Ayam Beku', 'Boneless Chicken Breast', null, array['fillet ayam','chicken breast','dada ayam']::text[], 'Dada ayam tanpa tulang dan kulit, untuk ayam geprek, katsu, dan menu sehat.', 'Boneless, skinless breast for geprek, katsu and healthy menus.', 'Rumah potong bersertifikat halal di Jawa Barat', 'Halal-certified slaughterhouse, West Java', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/dada-fillet-ayam.jpg', 'chicken', 28),
  ('p_ayam_segar', 'ayam-potong-segar', 'c_ayam', 'Ayam Potong Segar', 'Fresh Chicken, cut', null, array['ayam segar','ayam potong 8','broiler']::text[], 'Ayam broiler segar dari rumah potong bersertifikat halal, dipotong 8 atau 12. Khusus akun bisnis; harga mengikuti acuan pasar mingguan.', 'Fresh broiler cut into 8 or 12 from a halal-certified slaughterhouse. Business accounts only; priced to the weekly market index.', 'Rumah potong bersertifikat halal di Bogor', 'Halal-certified slaughterhouse, Bogor', 'chilled', 'Simpan pada suhu 0–4 °C. Dikemas terpisah dari ikan.', null, true, true, true, false, '/images/products/ayam-potong-segar.jpg', 'chicken', 29),
  ('p_ayam_utuh', 'ayam-utuh-beku', 'c_ayam', 'Ayam Utuh Beku', 'Whole Chicken', null, array['ayam utuh','whole chicken','ayam broiler']::text[], 'Ayam broiler utuh tanpa jeroan dari rumah potong bersertifikat halal, untuk ayam panggang, ayam bakar, atau kaldu.', 'Whole broiler without giblets from a halal-certified slaughterhouse, for roasting, grilling or stock.', 'Rumah potong bersertifikat halal di Jawa Barat', 'Halal-certified slaughterhouse, West Java', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, null, 'chicken', 30),
  ('p_paha_fillet', 'paha-fillet-ayam', 'c_ayam', 'Fillet Paha Ayam Beku', 'Boneless Chicken Thigh', null, array['paha fillet','boneless thigh','chicken thigh']::text[], 'Paha ayam tanpa tulang dengan kulit, juicy untuk ayam bakar, teriyaki, dan karaage.', 'Skin-on boneless thighs, juicy for grilled chicken, teriyaki and karaage.', 'Rumah potong bersertifikat halal di Jawa Barat', 'Halal-certified slaughterhouse, West Java', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, null, 'chicken', 31),
  ('p_nugget', 'nugget-ayam', 'c_olahan', 'Nugget Ayam', 'Chicken Nuggets', null, array['nugget','naget']::text[], 'Nugget ayam merek nasional, terdaftar di BPOM (MD) dan berlogo halal.', 'National-brand chicken nuggets, BPOM-registered with a halal logo.', 'Distributor resmi', 'Authorised distributor', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/nugget-ayam.jpg', 'box', 32),
  ('p_sosis', 'sosis-ayam', 'c_olahan', 'Sosis Ayam', 'Chicken Sausage', null, array['sosis','sausage']::text[], 'Sosis ayam premium untuk sarapan, bekal, dan menu kafe.', 'Premium chicken sausages for breakfast, bento and café menus.', 'Distributor resmi', 'Authorised distributor', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/sosis-ayam.jpg', 'box', 33),
  ('p_bakso', 'bakso-ikan', 'c_olahan', 'Bakso Ikan', 'Fish Balls', null, array['fish ball','baso ikan']::text[], 'Bakso ikan yang kenyal untuk sup, tom yam, dan suki.', 'Springy fish balls for soups, tom yum and steamboat.', 'Distributor resmi', 'Authorised distributor', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/bakso-ikan.jpg', 'box', 34),
  ('p_otak', 'otak-otak', 'c_olahan', 'Otak-otak Tenggiri', 'Grilled Fish Cake', null, array['otak otak','otak-otak bakar']::text[], 'Otak-otak tenggiri beku, cukup dibakar atau dikukus selama 10 menit.', 'Frozen Spanish-mackerel otak-otak; grill or steam for 10 minutes.', 'Produsen UMKM bersertifikat P-IRT', 'P-IRT-certified small producer', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, null, 'box', 35),
  ('p_siomay', 'siomay', 'c_olahan', 'Siomay Ayam Udang', 'Chicken & Prawn Siomay', null, array['siomay','dimsum','shumai']::text[], 'Siomay ayam dan udang beku, cukup dikukus 10 menit. Dari produsen terdaftar BPOM dan berlogo halal.', 'Frozen chicken and prawn siomay, ready after 10 minutes of steaming. BPOM-registered, halal-labelled producer.', 'Produsen terdaftar BPOM MD, Tangerang', 'BPOM MD-registered producer, Tangerang', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, null, 'box', 36),
  ('p_kentang', 'kentang-goreng-beku', 'c_olahan', 'Kentang Goreng Beku', 'Frozen French Fries', null, array['kentang','french fries','fries']::text[], 'Kentang goreng potongan 9 mm, renyah di luar dan lembut di dalam. Pendamping fish and chips dan menu anak.', '9 mm cut fries, crisp outside and fluffy inside. The partner for fish and chips and kids'' menus.', 'Distributor resmi produk impor', 'Authorised import distributor', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, null, 'box', 37),
  ('p_telur', 'telur-ayam', 'c_telur', 'Telur Ayam Negeri', 'Chicken Eggs', null, array['telur','egg','telor']::text[], 'Telur segar dari peternakan di Blitar dan Bogor, tiba di gudang kami dua kali seminggu.', 'Fresh eggs from Blitar and Bogor farms, delivered to our store twice a week.', 'Peternakan di Blitar dan Bogor', 'Blitar and Bogor farms', 'ambient', 'Simpan di tempat sejuk, gunakan dalam 2 minggu.', null, false, true, true, false, '/images/products/telur-ayam.jpg', 'egg', 38),
  ('p_telur_kampung', 'telur-ayam-kampung', 'c_telur', 'Telur Ayam Kampung', 'Free-range Chicken Eggs', null, array['telur kampung','free range','telur organik']::text[], 'Telur ayam kampung dari peternakan rakyat, berukuran lebih kecil dengan kuning berwarna jingga pekat.', 'Free-range eggs from smallholder farms: smaller, with deep orange yolks.', 'Peternakan rakyat di Sukabumi', 'Smallholder farms, Sukabumi', 'ambient', 'Simpan di tempat sejuk, gunakan dalam 2 minggu.', 'Keep cool; use within 2 weeks.', false, true, true, false, null, 'egg', 39),
  ('p_telur_bebek', 'telur-bebek', 'c_telur', 'Telur Bebek', 'Duck Eggs', null, array['telur bebek','duck egg','telur itik']::text[], 'Telur bebek segar dengan kuning yang pekat, untuk martabak, kue, dan telur asin buatan sendiri.', 'Fresh duck eggs with rich yolks, for martabak, cakes and home-made salted eggs.', 'Peternakan di Brebes dan Indramayu', 'Brebes and Indramayu farms', 'ambient', 'Simpan di tempat sejuk, gunakan dalam 2 minggu.', 'Keep cool; use within 2 weeks.', false, true, true, false, null, 'egg', 40),
  ('p_telur_puyuh', 'telur-puyuh', 'c_telur', 'Telur Puyuh', 'Quail Eggs', null, array['puyuh','quail egg']::text[], 'Telur puyuh segar untuk sate telur puyuh, sup, dan bekal anak.', 'Fresh quail eggs for skewers, soups and lunch boxes.', 'Peternakan di Bogor', 'Bogor farms', 'ambient', 'Simpan di kulkas, gunakan dalam 2 minggu.', 'Refrigerate; use within 2 weeks.', false, true, true, false, null, 'egg', 41),
  ('p_minyak', 'minyak-goreng', 'c_bumbu', 'Minyak Goreng', 'Cooking Oil', null, array['minyak','oil']::text[], 'Minyak goreng sawit dalam kemasan, merek nasional.', 'Packaged palm cooking oil, national brand.', 'Distributor resmi', 'FMCG distributor', 'ambient', 'Simpan di tempat yang sejuk dan kering.', 'Store in a cool, dry place.', false, true, true, false, '/images/products/minyak-goreng.jpg', 'bottle', 42),
  ('p_kecap', 'kecap-manis', 'c_bumbu', 'Kecap Manis', 'Sweet Soy Sauce', null, array['kecap','soy sauce']::text[], 'Kecap manis merek nasional, tersedia dalam botol atau jeriken untuk dapur restoran.', 'National-brand sweet soy sauce, bottle or jerrycan for restaurant kitchens.', 'Distributor resmi', 'FMCG distributor', 'ambient', 'Simpan di tempat yang sejuk dan kering.', 'Store in a cool, dry place.', false, true, true, false, '/images/products/kecap-manis.jpg', 'bottle', 43),
  ('p_sambal', 'sambal-bawang', 'c_bumbu', 'Sambal Bawang', 'Shallot Chili Paste', null, array['sambal','chili']::text[], 'Sambal bawang siap pakai, pendamping ikan bakar dan ayam goreng.', 'Ready-to-use shallot chilli paste, the partner of grilled fish and fried chicken.', 'Produsen UMKM terdaftar di BPOM', 'BPOM-registered small producer', 'ambient', 'Simpan di kulkas setelah dibuka.', null, false, true, true, false, '/images/products/sambal-bawang.jpg', 'bottle', 44),
  ('p_bawang', 'bawang-putih-kupas', 'c_bumbu', 'Bawang Putih Kupas', 'Peeled Garlic', null, array['garlic','bawang']::text[], 'Bawang putih kupas yang menghemat sekitar 30 menit pekerjaan dapur setiap hari.', 'Peeled garlic: saves 30 minutes of kitchen work every day.', 'Pasar Induk Kramat Jati', 'Kramat Jati wholesale market', 'chilled', 'Simpan pada suhu 0–4 °C; gunakan dalam 5 hari.', null, false, true, true, false, '/images/products/bawang-putih-kupas.jpg', 'bottle', 45),
  ('p_tepung', 'tepung-bumbu', 'c_bumbu', 'Tepung Bumbu Serbaguna', 'Seasoned Flour', null, array['tepung','flour','tepung crispy']::text[], 'Tepung bumbu untuk ayam dan seafood goreng tepung yang renyah.', 'Seasoned flour for crispy fried chicken and seafood.', 'Distributor resmi', 'FMCG distributor', 'ambient', 'Simpan di tempat yang sejuk dan kering.', 'Store in a cool, dry place.', false, true, true, false, '/images/products/tepung-bumbu.jpg', 'bottle', 46),
  ('p_saus_tiram', 'saus-tiram', 'c_bumbu', 'Saus Tiram', 'Oyster Sauce', null, array['saus tiram','oyster sauce','saori']::text[], 'Saus tiram untuk tumisan seafood, cah sayur, dan bumbu marinasi. Merek terdaftar BPOM dan berlogo halal.', 'Oyster sauce for seafood stir-fries, greens and marinades. BPOM-registered, halal-labelled brand.', 'Distributor resmi', 'FMCG distributor', 'ambient', 'Simpan di kulkas setelah dibuka.', 'Refrigerate after opening.', false, true, true, false, null, 'bottle', 47),
  ('p_minyak_wijen', 'minyak-wijen', 'c_bumbu', 'Minyak Wijen', 'Sesame Oil', null, array['minyak wijen','sesame oil']::text[], 'Minyak wijen sangrai beraroma kuat, cukup beberapa tetes untuk ikan kukus, bakmi, dan tumisan.', 'Fragrant toasted sesame oil; a few drops for steamed fish, noodles and stir-fries.', 'Distributor resmi', 'FMCG distributor', 'ambient', 'Simpan di tempat yang sejuk dan kering.', 'Store in a cool, dry place.', false, true, true, false, null, 'bottle', 48),
  ('p_garam_laut', 'garam-laut', 'c_bumbu', 'Garam Laut', 'Sea Salt', null, array['garam','sea salt','garam kasar']::text[], 'Garam laut kasar dari petambak garam Madura, untuk ikan bakar, garam rendaman ikan, dan masakan sehari-hari.', 'Coarse sea salt from Madura salt farmers, for grilled fish, brines and everyday cooking.', 'Petambak garam Madura', 'Madura salt farmers', 'ambient', 'Simpan di tempat yang sejuk dan kering.', 'Store in a cool, dry place.', false, true, true, false, null, 'bottle', 49),
  ('p_jeruk_nipis', 'jeruk-nipis', 'c_bumbu', 'Jeruk Nipis', 'Limes', 'Citrus aurantiifolia', array['jeruk nipis','lime','jeruk']::text[], 'Jeruk nipis segar untuk menghilangkan aroma amis, perasan ikan bakar, dan sambal.', 'Fresh limes to take away fishiness, squeeze over grilled fish and brighten sambal.', 'Pasar Induk Kramat Jati', 'Kramat Jati wholesale market', 'ambient', 'Simpan di kulkas, gunakan dalam 7 hari.', 'Refrigerate; use within 7 days.', false, true, true, false, null, 'bottle', 50),
  ('p_box_keluarga', 'kotak-freezer-keluarga', 'c_paket', 'Kotak Freezer Keluarga', 'Family Freezer Box', null, array['paket','bundle','freezer box','kotak hemat']::text[], 'Udang kupas belah punggung 500 g, fillet dori 1 kg, nugget ayam 500 g, dan sayap ayam 1 kg. Persediaan protein keluarga untuk seminggu, Rp9.000 lebih hemat daripada membeli satuan.', 'Peeled & deveined shrimp 500 g, dori fillet 1 kg, chicken nuggets 500 g and chicken wings 1 kg. A week of family protein, Rp9,000 below buying separately.', 'Dikemas di ruang pengemasan kami', 'Packed at our packing table', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/kotak-freezer-keluarga.jpg', 'box', 51),
  ('p_box_seafood', 'kotak-seafood-weekend', 'c_paket', 'Kotak Seafood Akhir Pekan', 'Weekend Seafood Box', null, array['paket','bundle','salmon box','kotak seafood']::text[], 'Fillet salmon 2 × 200 g, tuna saku 250 g, dan udang kupas belah punggung 500 g. Cukup untuk dua makan malam istimewa dan satu tumisan cepat, Rp21.000 lebih hemat daripada membeli satuan.', 'Salmon fillet 2 × 200 g, tuna saku 250 g and peeled & deveined shrimp 500 g. Two special dinners and one quick stir-fry, Rp21,000 below buying separately.', 'Dikemas di ruang pengemasan kami', 'Packed at our packing table', 'frozen', 'Simpan pada suhu −18 °C. Cairkan di bagian bawah kulkas, bukan pada suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/kotak-seafood-weekend.jpg', 'box', 52),
  ('p_paket_bakar', 'paket-ikan-bakar', 'c_paket', 'Paket Ikan Bakar', 'Grill Night Box', null, array['paket bakar','bbq','grill']::text[], 'Kakap putih ±1 kg yang sudah disiangi, cumi segar 500 g, sambal bawang, dan jeruk nipis 500 g. Cukup untuk 4–5 orang.', 'Barramundi ±1 kg (gutted), fresh squid 500 g, shallot sambal and limes 500 g. Serves 4–5.', 'Dikemas di ruang pengemasan kami', 'Packed at our packing table', 'chilled', 'Simpan pada suhu 0–4 °C, lalu masak dalam 24 jam atau segera bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', false, true, true, true, null, 'box', 53)
